(()=>{'use strict';
const D=window.MANEGE;D.rooms.onbekend={id:'onbekend',name:'Nog te bepalen',future:'Functionele vertaling nog uitvragen.',sharing:'Nog niet vastgesteld.',facilities:'Nog te bepalen.',current:'Niet vastgelegd.',unknown:'Ruimtefunctie uitvragen.',advice:[],design:'d1'};const base=JSON.parse(JSON.stringify(D)),cfg=window.MANEGE_BACKEND||{},listeners=new Set;
let records=[],talks=[],session=null,admin=false,error='',ready=false;
try{session=JSON.parse(sessionStorage.getItem('manege-admin-session')||'null');}catch{}
const configured=()=>/^https:\/\//.test(cfg.url)&&!!cfg.key||/^http:\/\/127\.0\.0\.1:\d+$/.test(cfg.url)&&location.hostname==='127.0.0.1'&&!!cfg.key;
const norm=s=>String(s||'').normalize('NFKC').trim().toLocaleLowerCase().replace(/\s+/g,' ');
const uid=()=>crypto.randomUUID();
async function request(path,options={},authenticated=false){if(!configured())throw Error('De beveiligde opslag is nog niet gekoppeld.');if(authenticated&&session?.expires_at<Date.now()/1000+30){const r=await fetch(cfg.url+'/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:{apikey:cfg.key,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:session.refresh_token})});if(!r.ok){session=null;admin=false;sessionStorage.removeItem('manege-admin-session');throw Error('Je sessie is verlopen. Log opnieuw in.');}session=await r.json();session.expires_at=Date.now()/1000+session.expires_in;sessionStorage.setItem('manege-admin-session',JSON.stringify(session));}
 const r=await fetch(cfg.url.replace(/\/$/,'')+path,{...options,headers:{apikey:cfg.key,...(authenticated&&session?{Authorization:'Bearer '+session.access_token}:{}),...options.headers}});if(!r.ok){let e={};try{e=await r.json();}catch{}throw Error(r.status===401||r.status===403?'Geen toegang. Log in als bevoegde beheerder.':e.message||e.error_description||'Opslaan of laden is mislukt ('+r.status+').');}if(r.status===204)return null;const txt=await r.text();return txt?JSON.parse(txt):null;}
function apply(){D.wishes=JSON.parse(JSON.stringify(base.wishes));D.sources=JSON.parse(JSON.stringify(base.sources));D.stakeholders=[...new Set([...base.wishes.map(w=>w.org),base.sources.V?.org].filter(Boolean))].map(name=>({id:name,name,role:'',description:''}));
 for(const r of records.filter(r=>r.kind==='stakeholder')){const old=D.stakeholders.find(x=>x.id===r.id||x.name===r.id);if(r.deleted){if(old)D.stakeholders=D.stakeholders.filter(x=>x!==old);continue;}const value={id:r.id,...r.data};if(old){const previous=old.name;Object.assign(old,value);D.wishes.forEach(w=>{if(w.org===previous)w.org=value.name;});}else D.stakeholders.push(value);}
 for(const r of records.filter(r=>r.kind==='wish')){D.wishes=D.wishes.filter(w=>w.id!==r.id&&!w.id.startsWith(r.id+'::'));if(r.deleted)continue;const item=r.data,orgIds=item.stakeholders||[item.org],orgs=orgIds.map(id=>D.stakeholders.find(s=>s.id===id)?.name||id).filter(Boolean);orgs.forEach((org,i)=>D.wishes.push({...item,id:i?r.id+'::'+i:r.id,recordId:r.id,org,advice:item.advice||[],design:item.design||D.rooms[item.room]?.design||'d1',source:item.source||'MANUAL',time:item.time||'Handmatige invoer',group:item.group||window.ManegeResearch?.groupOf(item)?.id}));}
 D.sources.MANUAL={id:'MANUAL',title:'Handmatig vastgelegde onderzoeksinformatie',org:'Onderzoek',file:'Beheerde bronrecords',date:'Per record vastgelegd',scope:'Invoer en beoordeling door een bevoegde beheerder.',limits:'Handmatige registratie is geen onafhankelijke validatie.'};
 for(const w of D.wishes)if(w.source&&!D.sources[w.source])D.sources[w.source]={id:w.source,title:'Gespreksbron',org:w.org,file:'Vertrouwelijke bron in beheeromgeving',date:'Zie gespreksregistratie',scope:'Door beheerder gekoppelde bronpassage.',limits:'De volledige transcriptie is niet openbaar.'};
 listeners.forEach(fn=>fn());}
async function load(){error='';try{if(configured()){records=await request('/rest/v1/manege_records?select=*&order=id',{},admin)||[];if(admin)talks=await request('/rest/v1/manege_talks?select=*&order=created_at.desc',{},true)||[];else talks=[];}apply();}catch(e){error=e.message;}ready=true;}
async function login(email,password){const result=await request('/auth/v1/token?grant_type=password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email,password})});session=result;session.expires_at=Date.now()/1000+result.expires_in;sessionStorage.setItem('manege-admin-session',JSON.stringify(session));const user=await request('/auth/v1/user',{},true);const rows=await request('/rest/v1/manege_admins?select=user_id&user_id=eq.'+encodeURIComponent(user.id),{},true);if(!rows?.length){await logout();throw Error('Dit account heeft geen beheerrechten.');}admin=true;await load();}
async function logout(){if(session)try{await request('/auth/v1/logout',{method:'POST'},true);}catch{}session=null;admin=false;talks=[];sessionStorage.removeItem('manege-admin-session');await load();}
function requireAdmin(){if(!admin)throw Error('Beheerderstoegang vereist.');}
function validate(kind,data,id){if(kind==='stakeholder'){data.name=String(data.name||'').trim();if(!data.name)throw Error('Vul een stakeholdernaam in.');if(D.stakeholders.some(s=>s.id!==id&&norm(s.name)===norm(data.name)))throw Error('Deze stakeholder bestaat al.');}
 if(kind==='wish'){if(!data.title?.trim()||!data.stakeholders?.length)throw Error('Kies een stakeholder en vul de omschrijving in.');if(!['Eis','Wens','Voorkeur','Idee','Aandachtspunt','Gebruikspatroon','Gebruikskader','Uit te vragen','Erkend aandachtspunt','Bereidheid tot delen'].includes(data.type))throw Error('Kies een geldig type.');if(!D.rooms[data.room])throw Error('Kies een bijbehorende functie.');for(const org of data.stakeholders){const name=D.stakeholders.find(s=>s.id===org)?.name||org;if(D.wishes.some(w=>(w.recordId||w.id)!==id&&w.org===name&&norm(w.title)===norm(data.title)))throw Error('Deze wens staat al bij '+name+'. Bewerk de bestaande registratie.');}}
 return data;}
async function save(kind,data,id=null,published=false){requireAdmin();id=id||uid();validate(kind,data,id);if(published&&kind==='wish'&&data.stakeholders.some(sid=>records.some(r=>r.id===sid&&r.kind==='stakeholder'&&!r.published)))throw Error('Maak eerst de gekoppelde stakeholder openbaar, of bewaar deze wens als concept.');const previous=records.find(x=>x.id===id),body={id,kind,data,published,deleted:false};let path='/rest/v1/manege_records',method='POST';if(previous){path+='?id=eq.'+encodeURIComponent(id)+'&updated_at=eq.'+encodeURIComponent(previous.updated_at);method='PATCH';delete body.id;}const saved=await request(path,{method,headers:{'Content-Type':'application/json',Prefer:'return=representation'},body:JSON.stringify(body)},true);if(!saved?.length)throw Error('Dit record is intussen gewijzigd. Herlaad en probeer opnieuw.');await load();return id;}
async function removeWish(id){requireAdmin();const w=D.wishes.find(x=>(x.recordId||x.id)===id);if(!w)return;const r=records.find(x=>x.id===id);if(!r){await save('wish',{...w,stakeholders:[D.stakeholders.find(s=>s.name===w.org)?.id||w.org]},id,false);}await request('/rest/v1/manege_records?id=eq.'+encodeURIComponent(id),{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({deleted:true,published:true,data:{}})},true);await load();}
async function saveTalk(data,file){requireAdmin();if(!data.stakeholder_id||!data.title?.trim()||(!data.body?.trim()&&!file))throw Error('Stakeholder, titel en gesprekstekst of bestand zijn verplicht.');const id=uid();let filePath=null;if(file){if(file.size>20*1024*1024)throw Error('Bestand is groter dan 20 MB.');const ext=file.name.split('.').pop().toLowerCase();if(!['pdf','docx','txt'].includes(ext))throw Error('Kies PDF, DOCX of TXT.');filePath=id+'/bron.'+ext;await request('/storage/v1/object/manege-private/'+filePath,{method:'POST',headers:{'Content-Type':file.type||'application/octet-stream'},body:file},true);if(ext==='txt'&&!data.body)data.body=await file.text();}
 const body={id,...data,file_path:filePath,file_name:file?.name||null,proposals:propose(data.body||'')};try{await request('/rest/v1/manege_talks',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)},true);}catch(e){if(filePath)try{await request('/storage/v1/object/manege-private',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({prefixes:[filePath]})},true);}catch{}throw e;}await load();return id;}
function propose(body){return body.split(/\n|(?<=[.!?])\s+/).map(s=>s.trim()).filter(s=>s.length>=12&&s.length<=900&&/\b(nodig|moet|wens|willen|wil|belangrijk|behoefte|vereist|graag)\b/i.test(s)).slice(0,40).map((text,i)=>({id:i,text,start:body.indexOf(text),state:'pending'}));}
async function updateProposals(id,proposals){requireAdmin();await request('/rest/v1/manege_talks?id=eq.'+encodeURIComponent(id),{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({proposals})},true);await load();}
async function downloadTalk(t){requireAdmin();const r=await fetch(cfg.url+'/storage/v1/object/authenticated/manege-private/'+t.file_path,{headers:{apikey:cfg.key,Authorization:'Bearer '+session.access_token}});if(!r.ok)throw Error('Bestand niet beschikbaar of geen toegang.');const url=URL.createObjectURL(await r.blob()),a=document.createElement('a');a.href=url;a.download=t.file_name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
async function start(){if(session&&configured())try{const user=await request('/auth/v1/user',{},true);admin=!!(await request('/rest/v1/manege_admins?select=user_id&user_id=eq.'+encodeURIComponent(user.id),{},true))?.length;}catch{session=null;sessionStorage.removeItem('manege-admin-session');}await load();}
window.ManegeStore={configured,norm,validate,propose,login,logout,save,removeWish,saveTalk,updateProposals,downloadTalk,load,start,apply,onChange:fn=>listeners.add(fn),get state(){return{admin,ready,error,records,talks};}};
})();
